@login_required
def edit_payout_schedule(request):
    if request.method == 'POST':
        schedule_id = request.POST.get('schedule_id')
        schedule = get_object_or_404(PayoutSchedule, id=schedule_id, contractor=request.user)
        form = PayoutScheduleForm(request.POST, instance=schedule)
        if form.is_valid():
            form.save()
            messages.success(request, "Payout schedule updated.")
            return redirect('payout_overview')
    else:
        schedule = request.user.payout_schedule
        form = PayoutScheduleForm(instance=schedule)
    return render(request, 'billing/payout_form.html', {'form': form})
